using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Pricing;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Pricing;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Pricing;
#pragma warning disable CA1725, CA1862

public sealed class PricingAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,IAuditWriter audit,TimeProvider time) : IPricingAdministration,IOrderPricingEngine
{
    private Guid Company => company.RequireCompanyId(); private DateTimeOffset Now => time.GetUtcNow();
    public Task<Result<TariffView>> CreateTariffAsync(TariffCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ if(c.PriceGroupId is not null&&!await ValidLookup(c.PriceGroupId.Value,"price.group",t))return Result.Failure<TariffView>(PricingErrors.InvalidData); Result<Tariff> made=Tariff.Create(Company,c.TariffType,c.Code,c.ProductVariantId,c.PrintPositionCode,c.PrintMethodCode,c.Amount,c.CurrencyCode,c.ValidFrom,c.ValidTo,Now,c.PriceGroupId);if(made.IsFailure)return Result.Failure<TariffView>(made.Error);if(await Overlaps(made.Value,null,t))return Result.Failure<TariffView>(PricingErrors.Overlap);db.Tariffs.Add(made.Value);Log("pricing.tariff.created",made.Value.Id);return Result.Success(View(made.Value));},ct);
    public Task<Result<TariffView>> UpdateTariffAsync(Guid id,TariffCommand c,bool active,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(c.PriceGroupId is not null&&!await ValidLookup(c.PriceGroupId.Value,"price.group",t))return Result.Failure<TariffView>(PricingErrors.InvalidData);Tariff? x=await db.Tariffs.SingleOrDefaultAsync(x=>x.Id==id,t);if(x is null)return Result.Failure<TariffView>(PricingErrors.NotFound);if(x.TariffType!=c.TariffType||x.Code!=c.Code.Trim().ToUpperInvariant()||x.ProductVariantId!=c.ProductVariantId)return Result.Failure<TariffView>(PricingErrors.InvalidData);Result r=x.Update(c.Amount,c.ValidFrom,c.ValidTo,active,c.Version,Now,c.PriceGroupId);if(r.IsFailure)return Result.Failure<TariffView>(r.Error);if(active&&await Overlaps(x,id,t))return Result.Failure<TariffView>(PricingErrors.Overlap);Log(active?"pricing.tariff.updated":"pricing.tariff.deactivated",id);return Result.Success(View(x));},ct);
    public Task<Result<IReadOnlyList<TariffView>>> ListTariffsAsync(TariffType? type,bool includeInactive,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<Tariff> q=db.Tariffs.AsNoTracking();if(type is not null)q=q.Where(x=>x.TariffType==type);if(!includeInactive)q=q.Where(x=>x.IsActive);return Result.Success<IReadOnlyList<TariffView>>((await q.OrderBy(x=>x.TariffType).ThenBy(x=>x.Code).ThenByDescending(x=>x.ValidFrom).ToListAsync(t)).Select(View).ToArray());},ct);
    public Task<Result<Guid>> CreateDiscountRuleAsync(DiscountRuleCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(c.CustomerGroupId is not null&&!await ValidLookup(c.CustomerGroupId.Value,"customer.group",t))return Result.Failure<Guid>(PricingErrors.InvalidData);Result<DiscountRule> r=DiscountRule.Create(Company,c.Code,c.DiscountType,c.Scope,c.CustomerId,c.Source,c.Value,c.CurrencyCode,c.ValidFrom,c.ValidTo,Now,c.CustomerGroupId);if(r.IsFailure)return Result.Failure<Guid>(r.Error);bool overlap=await db.DiscountRules.AnyAsync(x=>x.IsActive&&x.Code==c.Code.Trim().ToUpperInvariant()&&x.ValidFrom<=(c.ValidTo??DateOnly.MaxValue)&&(x.ValidTo==null||x.ValidTo>=c.ValidFrom),t);if(overlap)return Result.Failure<Guid>(PricingErrors.Overlap);db.Add(r.Value);Log("pricing.discount.created",r.Value.Id);return Result.Success(r.Value.Id);},ct);
    public Task<Result<Guid>> CreateTaxRuleAsync(TaxRuleCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Result<TaxRule> r=TaxRule.Create(Company,c.Code,c.RatePercent,c.IsExempt,c.ValidFrom,c.ValidTo,Now,c.TaxStatusCode);if(r.IsFailure)return Result.Failure<Guid>(r.Error);bool overlap=await db.TaxRules.AnyAsync(x=>x.IsActive&&x.Code==c.Code.Trim().ToUpperInvariant()&&(x.TaxStatusCode==null?c.TaxStatusCode==null:c.TaxStatusCode!=null&&EF.Functions.ILike(x.TaxStatusCode,c.TaxStatusCode))&&x.ValidFrom<=(c.ValidTo??DateOnly.MaxValue)&&(x.ValidTo==null||x.ValidTo>=c.ValidFrom),t);if(overlap)return Result.Failure<Guid>(PricingErrors.Overlap);db.Add(r.Value);Log("pricing.tax.created",r.Value.Id);return Result.Success(r.Value.Id);},ct);
    public Task<Result<OrderPricingView>> RecalculateAsync(Guid orderId,long orderVersion,ManualDiscountCommand? manual,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Order? order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==orderId,t);if(order is null)return Result.Failure<OrderPricingView>(PricingErrors.NotFound);if(order.Status!=OrderStatus.Draft)return Result.Failure<OrderPricingView>(PricingErrors.NotDraft);if(order.Version!=orderVersion)return Result.Failure<OrderPricingView>(PricingErrors.Concurrency);Result<OrderPricingView> r=await CalculateInsideTransactionAsync(order,false,manual,t);if(r.IsSuccess)Log("pricing.order.recalculated",orderId);return r;},ct);
    public Task<Result<OrderPricingView>> GetOrderPricingAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>await db.Orders.AnyAsync(x=>x.Id==orderId,t)?await Current(orderId,t):Result.Failure<OrderPricingView>(PricingErrors.NotFound),ct);
    public async Task<Result<OrderPricingView>> CalculateInsideTransactionAsync(Order order,bool finalize,ManualDiscountCommand? manual,CancellationToken t,bool allowSubmittedRevision=false)
    {
        if(order.Status!=OrderStatus.Draft&&!(allowSubmittedRevision&&order.Status==OrderStatus.Submitted))return Result.Failure<OrderPricingView>(PricingErrors.NotDraft);if(manual is not null&&(manual.Value<0||manual.Type==DiscountType.Percentage&&manual.Value>100))return Result.Failure<OrderPricingView>(PricingErrors.InvalidData);
        DateOnly date=order.OrderDate;Customer? customer=await db.Customers.SingleOrDefaultAsync(x=>x.Id==order.CustomerId,t);if(customer is null)return Result.Failure<OrderPricingView>(PricingErrors.NotFound);CustomerFinancialProfile? financial=await db.CustomerFinancialProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.CustomerId==customer.Id,t);List<OrderItem> items=await db.OrderItems.Where(x=>x.OrderId==order.Id&&x.IsActive).OrderBy(x=>x.LineNumber).ToListAsync(t);List<OrderPrintOperation> prints=await db.OrderPrintOperations.Where(x=>x.OrderId==order.Id&&x.IsActive).ToListAsync(t);List<Tariff> tariffs=await db.Tariffs.Where(x=>x.IsActive&&x.ValidFrom<=date&&(x.ValidTo==null||x.ValidTo>=date)&&(x.PriceGroupId==null||x.PriceGroupId==customer.PriceGroupId)).ToListAsync(t);if(items.Count==0)return Result.Failure<OrderPricingView>(PricingErrors.MissingTariff);
        var itemParts=new List<(OrderItem Item,decimal Raw,decimal Print,List<(OrderPrintOperation Op,Tariff Tariff,decimal Total)> Prints)>();string? currency=null;
        foreach(OrderItem item in items){Tariff? raw=ResolveTariff(tariffs,customer.PriceGroupId,TariffType.RawProduct,item.ProductVariantId,null,null);if(raw is null&&tariffs.Count==0)raw=Tariff.Create(Company,TariffType.RawProduct,"UNCONFIGURED",item.ProductVariantId,null,null,0,"IRR",date,null,Now).Value;if(raw is null)return Result.Failure<OrderPricingView>(PricingErrors.MissingTariff);if(currency is not null&&currency!=raw.CurrencyCode)return Result.Failure<OrderPricingView>(PricingErrors.InvalidCurrency);currency=raw.CurrencyCode;var pp=new List<(OrderPrintOperation,Tariff,decimal)>();foreach(OrderPrintOperation op in prints.Where(x=>x.OrderItemId==item.Id)){Tariff? pt=ResolveTariff(tariffs,customer.PriceGroupId,TariffType.Print,null,op.PrintPositionCode,op.PrintMethodCode);if(pt is null)return Result.Failure<OrderPricingView>(PricingErrors.MissingTariff);if(pt.CurrencyCode!=currency)return Result.Failure<OrderPricingView>(PricingErrors.InvalidCurrency);pp.Add((op,pt,Money.Round(pt.Amount*item.Quantity)));}itemParts.Add((item,Money.Round(raw.Amount*item.Quantity),pp.Sum(x=>x.Item3),pp));}
        Tariff? packaging=ResolveTariff(tariffs,customer.PriceGroupId,TariffType.Packaging,null,null,null,"DEFAULT");Tariff? shipping=ResolveTariff(tariffs,customer.PriceGroupId,TariffType.Shipping,null,null,null,"DEFAULT");List<Tariff> services=tariffs.Where(x=>x.TariffType==TariffType.AdditionalService&&(x.PriceGroupId==customer.PriceGroupId||x.PriceGroupId is null)).GroupBy(x=>x.Code).Select(g=>g.OrderByDescending(x=>x.PriceGroupId==customer.PriceGroupId).First()).ToList();foreach(Tariff x in tariffs.Where(x=>x.TariffType is TariffType.Packaging or TariffType.Shipping or TariffType.AdditionalService))if(x.CurrencyCode!=currency)return Result.Failure<OrderPricingView>(PricingErrors.InvalidCurrency);
        decimal rawTotal=itemParts.Sum(x=>x.Raw),printTotal=itemParts.Sum(x=>x.Print),serviceTotal=services.Sum(x=>x.Amount),packTotal=packaging?.Amount??0,shipTotal=shipping?.Amount??0;decimal subtotal=Money.Round(rawTotal+printTotal+serviceTotal+packTotal+shipTotal);
        DiscountRule? rule=null;decimal discount=0;if(manual is not null)discount=manual.Type==DiscountType.FixedAmount?manual.Value:Money.Round(subtotal*manual.Value/100m);else{List<DiscountRule> rules=await db.DiscountRules.Where(x=>x.IsActive&&x.ValidFrom<=date&&(x.ValidTo==null||x.ValidTo>=date)).ToListAsync(t);rule=rules.Where(x=>x.Applies(date,order.CustomerId,customer.CustomerGroupId,order.Source)&&x.CurrencyCode==currency).OrderByDescending(x=>x.Scope switch{DiscountScope.Customer=>4,DiscountScope.CustomerGroup=>3,DiscountScope.PartnerSource=>2,_=>1}).ThenByDescending(x=>x.Version).FirstOrDefault();if(rule is not null)discount=rule.DiscountType==DiscountType.FixedAmount?rule.Value:Money.Round(subtotal*rule.Value/100m);}discount=Math.Min(discount,subtotal);
        string? taxStatus=financial?.TaxStatusCode;TaxRule? tax=await db.TaxRules.Where(x=>x.IsActive&&x.ValidFrom<=date&&(x.ValidTo==null||x.ValidTo>=date)&&(x.Code=="DEFAULT"||x.Code=="TAX"||(taxStatus!=null&&x.TaxStatusCode!=null&&EF.Functions.ILike(x.TaxStatusCode,taxStatus)))).OrderByDescending(x=>taxStatus!=null&&x.TaxStatusCode!=null&&EF.Functions.ILike(x.TaxStatusCode,taxStatus)).ThenByDescending(x=>x.Version).FirstOrDefaultAsync(t);decimal taxRate=tax?.RatePercent??0;bool exempt=tax?.IsExempt??false;
        OrderPriceSnapshot? old=await db.OrderPriceSnapshots.SingleOrDefaultAsync(x=>x.OrderId==order.Id&&x.IsCurrent,t);if(old is not null){if(old.IsFinalized&&!allowSubmittedRevision)return Result.Success(await BuildView(old,t));Result superseded=old.IsFinalized?old.SupersedeForApprovedRevision():old.Supersede();if(superseded.IsFailure)return Result.Failure<OrderPricingView>(superseded.Error);}
        OrderPriceSnapshot snapshot=OrderPriceSnapshot.Create(Company,order.Id,currency!,rawTotal,printTotal,serviceTotal,packTotal,shipTotal,discount,taxRate,exempt,finalize,Now);db.Add(snapshot);if(!finalize)order.MarkPricingRecalculated(Now);decimal itemBase=itemParts.Sum(x=>x.Raw+x.Print);decimal allocated=0;
        foreach(var part in itemParts){decimal d=itemBase==0?0:Money.Round(discount*(part.Raw+part.Print)/itemBase);if(part==itemParts[^1])d=Money.Round(discount-allocated);allocated+=d;db.Add(OrderItemPriceSnapshot.Create(Company,snapshot.Id,part.Item.Id,part.Raw,part.Print,0,d,taxRate,exempt));Tariff? rawTariff=ResolveTariff(tariffs,customer.PriceGroupId,TariffType.RawProduct,part.Item.ProductVariantId,null,null);db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,part.Item.Id,null,rawTariff,PriceComponentType.RawProduct,rawTariff?.Code??"UNCONFIGURED",rawTariff?.Amount??0,part.Item.Quantity,part.Raw));foreach(var p in part.Prints)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,part.Item.Id,p.Op.Id,p.Tariff,PriceComponentType.Print,p.Tariff.Code,p.Tariff.Amount,part.Item.Quantity,p.Total));}
        foreach(Tariff s in services)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,null,null,s,PriceComponentType.AdditionalService,s.Code,s.Amount,1,s.Amount));if(packaging is not null)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,null,null,packaging,PriceComponentType.Packaging,packaging.Code,packaging.Amount,1,packaging.Amount));if(shipping is not null)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,null,null,shipping,PriceComponentType.Shipping,shipping.Code,shipping.Amount,1,shipping.Amount));if(discount>0)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,null,null,null,PriceComponentType.Discount,manual is null?rule?.Code??"DISCOUNT":"MANUAL",discount,1,-discount,manual is null?rule?.Id:null,manual is null?rule?.Version:null));if(snapshot.TaxTotal>0)db.Add(PriceComponentSnapshot.Create(Company,snapshot.Id,null,null,null,PriceComponentType.Tax,tax?.Code??"DEFAULT",taxRate,1,snapshot.TaxTotal,tax?.Id,tax?.Version));if(finalize)Log("pricing.order.finalized",order.Id);return Result.Success(await BuildView(snapshot,t));
    }
    private static Tariff? ResolveTariff(IEnumerable<Tariff> tariffs,Guid? priceGroup,TariffType type,Guid? variant,string? position,string? method,string? code=null)=>tariffs.Where(x=>x.TariffType==type&&(variant is null||x.ProductVariantId==variant)&&(code is null||x.Code==code)&&(position is null||x.PrintPositionCode==position)&&(method is null||x.PrintMethodCode is null||x.PrintMethodCode==method)&&(x.PriceGroupId==priceGroup||x.PriceGroupId is null)).OrderByDescending(x=>x.PriceGroupId==priceGroup).ThenByDescending(x=>x.PrintMethodCode==method&&method is not null).FirstOrDefault();
    private Task<bool> Overlaps(Tariff x,Guid? exclude,CancellationToken t)=>db.Tariffs.AnyAsync(y=>y.Id!=exclude&&y.IsActive&&y.TariffType==x.TariffType&&y.Code==x.Code&&y.ProductVariantId==x.ProductVariantId&&y.PriceGroupId==x.PriceGroupId&&y.PrintPositionCode==x.PrintPositionCode&&y.PrintMethodCode==x.PrintMethodCode&&y.ValidFrom<=(x.ValidTo??DateOnly.MaxValue)&&(y.ValidTo==null||y.ValidTo>=x.ValidFrom),t);
    private async Task<Result<OrderPricingView>> Current(Guid order,CancellationToken t){OrderPriceSnapshot? x=await db.OrderPriceSnapshots.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==order&&x.IsCurrent,t);return x is null?Result.Failure<OrderPricingView>(PricingErrors.NotFound):Result.Success(await BuildView(x,t));}
    private async Task<OrderPricingView> BuildView(OrderPriceSnapshot x,CancellationToken t){var persistedItems=await db.OrderItemPriceSnapshots.AsNoTracking().Where(i=>i.OrderPriceSnapshotId==x.Id).ToListAsync(t);persistedItems.AddRange(db.OrderItemPriceSnapshots.Local.Where(i=>i.OrderPriceSnapshotId==x.Id&&!persistedItems.Any(p=>p.Id==i.Id)));var items=persistedItems.Select(i=>new OrderItemPricingView(i.OrderItemId,i.RawProductTotal,i.PrintTotal,i.AdditionalServiceTotal,i.Subtotal,i.DiscountAllocated,i.TaxableAmount,i.TaxAmount,i.FinalTotal)).ToArray();var persistedParts=await db.PriceComponentSnapshots.AsNoTracking().Where(p=>p.OrderPriceSnapshotId==x.Id).ToListAsync(t);persistedParts.AddRange(db.PriceComponentSnapshots.Local.Where(i=>i.OrderPriceSnapshotId==x.Id&&!persistedParts.Any(p=>p.Id==i.Id)));var parts=persistedParts.Select(p=>new PriceComponentView(p.Id,p.OrderItemId,p.OrderPrintOperationId,p.ComponentType,p.TariffCode,p.UnitAmount,p.Quantity,p.TotalAmount)).ToArray();return new(x.Id,x.OrderId,x.CurrencyCode,x.RawProductTotal,x.PrintTotal,x.AdditionalServiceTotal,x.PackagingTotal,x.ShippingTotal,x.Subtotal,x.DiscountTotal,x.TaxableTotal,x.TaxTotal,x.FinalTotal,x.TaxRatePercent,x.IsTaxExempt,x.IsFinalized,x.CalculatedAtUtc,x.Version,items,parts);}
    private async Task<bool> ValidLookup(Guid id,string typeCode,CancellationToken t)=>await (from v in db.LookupValues join k in db.LookupTypes on v.LookupTypeId equals k.Id where v.Id==id&&v.IsActive&&v.CompanyId==Company&&k.Code==typeCode&&k.IsActive select v).AnyAsync(t);
    private static TariffView View(Tariff x)=>new(x.Id,x.TariffType,x.Code,x.ProductVariantId,x.PriceGroupId,x.PrintPositionCode,x.PrintMethodCode,x.Amount,x.CurrencyCode,x.ValidFrom,x.ValidTo,x.IsActive,x.Version);private void Log(string action,Guid id)=>audit.Write(new(action,"pricing",id.ToString(),ChangeKind:AuditChangeKind.Modified));
}
#pragma warning restore CA1725, CA1862
